-- 家政服务工单调度与服务质量追踪管理系统数据库结构
CREATE DATABASE IF NOT EXISTS jiazheng_system DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE jiazheng_system;

SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS operation_log, login_log, sys_config, sys_notice, complaint_record, complaint,
service_review, service_image, service_process, work_order_status_log, work_order_assignment,
work_order, service_demand, customer_address, provider_skill, provider_profile, customer_profile,
service_item, service_category, service_region, sys_user_role, sys_role_menu, sys_menu, sys_role, sys_user;
SET FOREIGN_KEY_CHECKS = 1;

CREATE TABLE sys_user (
 id BIGINT PRIMARY KEY COMMENT '用户主键', username VARCHAR(50) NOT NULL UNIQUE COMMENT '登录账号',
 password VARCHAR(100) NOT NULL COMMENT 'BCrypt密码摘要', real_name VARCHAR(50) NOT NULL COMMENT '真实姓名',
 phone VARCHAR(20) NOT NULL UNIQUE COMMENT '联系电话', id_card VARCHAR(18) COMMENT '模拟身份证号',
 user_type TINYINT NOT NULL COMMENT '1管理员 2服务人员 3客户', status TINYINT NOT NULL DEFAULT 1 COMMENT '1启用 0停用',
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) COMMENT='系统用户';
CREATE TABLE sys_role (id BIGINT PRIMARY KEY, role_code VARCHAR(30) UNIQUE NOT NULL, role_name VARCHAR(50) NOT NULL, description VARCHAR(200)) COMMENT='角色';
CREATE TABLE sys_menu (id BIGINT PRIMARY KEY, parent_id BIGINT DEFAULT 0, menu_name VARCHAR(50) NOT NULL, menu_type CHAR(1) NOT NULL COMMENT 'M目录 C菜单 F按钮', path VARCHAR(100), permission VARCHAR(100), sort_no INT DEFAULT 0) COMMENT='菜单权限';
CREATE TABLE sys_user_role (user_id BIGINT NOT NULL, role_id BIGINT NOT NULL, PRIMARY KEY(user_id, role_id), FOREIGN KEY(user_id) REFERENCES sys_user(id), FOREIGN KEY(role_id) REFERENCES sys_role(id)) COMMENT='用户角色关联';
CREATE TABLE sys_role_menu (role_id BIGINT NOT NULL, menu_id BIGINT NOT NULL, PRIMARY KEY(role_id, menu_id), FOREIGN KEY(role_id) REFERENCES sys_role(id), FOREIGN KEY(menu_id) REFERENCES sys_menu(id)) COMMENT='角色菜单关联';

CREATE TABLE service_region (id BIGINT PRIMARY KEY, region_name VARCHAR(50) NOT NULL, province VARCHAR(30) NOT NULL, city VARCHAR(30) NOT NULL, district VARCHAR(30) NOT NULL, status TINYINT DEFAULT 1) COMMENT='服务区域';
CREATE TABLE service_category (id BIGINT PRIMARY KEY, category_name VARCHAR(50) NOT NULL, description VARCHAR(200), status TINYINT DEFAULT 1) COMMENT='服务分类';
CREATE TABLE service_item (id BIGINT PRIMARY KEY, category_id BIGINT NOT NULL, item_name VARCHAR(80) NOT NULL, service_duration INT NOT NULL COMMENT '预计分钟', description VARCHAR(500), status TINYINT DEFAULT 1, FOREIGN KEY(category_id) REFERENCES service_category(id)) COMMENT='服务项目';
CREATE TABLE customer_profile (user_id BIGINT PRIMARY KEY, contact_name VARCHAR(50), emergency_phone VARCHAR(20), remark VARCHAR(200), FOREIGN KEY(user_id) REFERENCES sys_user(id)) COMMENT='客户资料';
CREATE TABLE provider_profile (user_id BIGINT PRIMARY KEY, skill_level VARCHAR(30), work_status VARCHAR(20) DEFAULT '空闲' COMMENT '空闲 忙碌 停用', years_experience INT DEFAULT 0, service_area_id BIGINT, training_status VARCHAR(20) DEFAULT '已培训', introduction VARCHAR(500), FOREIGN KEY(user_id) REFERENCES sys_user(id), FOREIGN KEY(service_area_id) REFERENCES service_region(id)) COMMENT='服务人员资料';
CREATE TABLE provider_skill (provider_id BIGINT NOT NULL, service_item_id BIGINT NOT NULL, skill_level VARCHAR(20) DEFAULT '熟练', PRIMARY KEY(provider_id, service_item_id), FOREIGN KEY(provider_id) REFERENCES provider_profile(user_id), FOREIGN KEY(service_item_id) REFERENCES service_item(id)) COMMENT='服务人员技能';
CREATE TABLE customer_address (id BIGINT PRIMARY KEY, customer_id BIGINT NOT NULL, receiver_name VARCHAR(50) NOT NULL, receiver_phone VARCHAR(20) NOT NULL, province VARCHAR(30), city VARCHAR(30), district VARCHAR(30), detail_address VARCHAR(200) NOT NULL, is_default TINYINT DEFAULT 0, FOREIGN KEY(customer_id) REFERENCES customer_profile(user_id)) COMMENT='客户服务地址';

CREATE TABLE service_demand (id BIGINT PRIMARY KEY, demand_no VARCHAR(40) UNIQUE NOT NULL, customer_id BIGINT NOT NULL, service_item_id BIGINT NOT NULL, address_id BIGINT NOT NULL, expected_date DATE NOT NULL, expected_time VARCHAR(30), description VARCHAR(500), status VARCHAR(20) DEFAULT '待审核', created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(customer_id) REFERENCES customer_profile(user_id), FOREIGN KEY(service_item_id) REFERENCES service_item(id), FOREIGN KEY(address_id) REFERENCES customer_address(id)) COMMENT='客户服务需求';
CREATE TABLE work_order (id BIGINT PRIMARY KEY, order_no VARCHAR(40) UNIQUE NOT NULL, demand_id BIGINT UNIQUE NOT NULL, customer_id BIGINT NOT NULL, provider_id BIGINT, service_item_id BIGINT NOT NULL, address_id BIGINT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT '待审核', priority TINYINT DEFAULT 2, scheduled_date DATE, scheduled_time VARCHAR(30), cancel_reason VARCHAR(300), completed_at DATETIME, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(demand_id) REFERENCES service_demand(id), FOREIGN KEY(customer_id) REFERENCES customer_profile(user_id), FOREIGN KEY(provider_id) REFERENCES provider_profile(user_id), FOREIGN KEY(service_item_id) REFERENCES service_item(id), FOREIGN KEY(address_id) REFERENCES customer_address(id)) COMMENT='服务工单';
CREATE TABLE work_order_assignment (id BIGINT PRIMARY KEY, order_id BIGINT NOT NULL, provider_id BIGINT NOT NULL, assign_type VARCHAR(20) NOT NULL COMMENT '规则推荐 人工指定', match_score DECIMAL(5,2), match_reason VARCHAR(500), assign_status VARCHAR(20) DEFAULT '已分配', assigned_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES work_order(id), FOREIGN KEY(provider_id) REFERENCES provider_profile(user_id)) COMMENT='工单调度记录';
CREATE TABLE work_order_status_log (id BIGINT PRIMARY KEY, order_id BIGINT NOT NULL, from_status VARCHAR(20), to_status VARCHAR(20) NOT NULL, operator_id BIGINT NOT NULL, remark VARCHAR(300), created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES work_order(id), FOREIGN KEY(operator_id) REFERENCES sys_user(id)) COMMENT='工单状态流转记录';
CREATE TABLE service_process (id BIGINT PRIMARY KEY, order_id BIGINT NOT NULL, provider_id BIGINT NOT NULL, process_type VARCHAR(20) NOT NULL COMMENT '签到 开始 暂停 完成', process_time DATETIME NOT NULL, description VARCHAR(500), longitude DECIMAL(10,6), latitude DECIMAL(10,6), FOREIGN KEY(order_id) REFERENCES work_order(id), FOREIGN KEY(provider_id) REFERENCES provider_profile(user_id)) COMMENT='服务过程记录';
CREATE TABLE service_image (id BIGINT PRIMARY KEY, order_id BIGINT NOT NULL, process_id BIGINT, image_type VARCHAR(20) NOT NULL COMMENT '服务前 服务后 验收', image_url VARCHAR(500) NOT NULL, description VARCHAR(200), created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES work_order(id), FOREIGN KEY(process_id) REFERENCES service_process(id)) COMMENT='服务图片';
CREATE TABLE service_review (id BIGINT PRIMARY KEY, order_id BIGINT UNIQUE NOT NULL, customer_id BIGINT NOT NULL, provider_id BIGINT NOT NULL, score TINYINT NOT NULL, content VARCHAR(500), image_urls VARCHAR(1000), reply_content VARCHAR(500), created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES work_order(id), FOREIGN KEY(customer_id) REFERENCES customer_profile(user_id), FOREIGN KEY(provider_id) REFERENCES provider_profile(user_id)) COMMENT='验收评价';
CREATE TABLE complaint (id BIGINT PRIMARY KEY, complaint_no VARCHAR(40) UNIQUE NOT NULL, order_id BIGINT NOT NULL, customer_id BIGINT NOT NULL, complaint_type VARCHAR(30) NOT NULL, content VARCHAR(500) NOT NULL, status VARCHAR(20) DEFAULT '待处理', result VARCHAR(500), created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES work_order(id), FOREIGN KEY(customer_id) REFERENCES customer_profile(user_id)) COMMENT='投诉返工';
CREATE TABLE complaint_record (id BIGINT PRIMARY KEY, complaint_id BIGINT NOT NULL, operator_id BIGINT NOT NULL, action VARCHAR(30) NOT NULL, content VARCHAR(500), created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(complaint_id) REFERENCES complaint(id), FOREIGN KEY(operator_id) REFERENCES sys_user(id)) COMMENT='投诉处理记录';
CREATE TABLE sys_notice (id BIGINT PRIMARY KEY, title VARCHAR(100) NOT NULL, content TEXT NOT NULL, notice_type VARCHAR(20) DEFAULT '系统公告', publish_status TINYINT DEFAULT 1, publisher_id BIGINT NOT NULL, published_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(publisher_id) REFERENCES sys_user(id)) COMMENT='系统通知';
CREATE TABLE login_log (id BIGINT PRIMARY KEY, user_id BIGINT, username VARCHAR(50), login_ip VARCHAR(50), login_status TINYINT, message VARCHAR(200), created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES sys_user(id)) COMMENT='登录日志';
CREATE TABLE operation_log (id BIGINT PRIMARY KEY, operator_id BIGINT, module_name VARCHAR(50), operation_name VARCHAR(100), request_method VARCHAR(10), request_url VARCHAR(200), result_status TINYINT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(operator_id) REFERENCES sys_user(id)) COMMENT='操作日志';
CREATE TABLE sys_config (config_key VARCHAR(80) PRIMARY KEY, config_value VARCHAR(500) NOT NULL, config_name VARCHAR(100) NOT NULL, remark VARCHAR(200)) COMMENT='系统配置';

CREATE INDEX idx_order_status ON work_order(status); CREATE INDEX idx_order_customer ON work_order(customer_id); CREATE INDEX idx_order_provider ON work_order(provider_id); CREATE INDEX idx_demand_date ON service_demand(expected_date); CREATE INDEX idx_process_order ON service_process(order_id); CREATE INDEX idx_complaint_status ON complaint(status);
